import { bigint, index, integer, jsonb, pgEnum, pgTable, text, uniqueIndex } from "drizzle-orm/pg-core";
import { createdAt, deletedAt, id, timestamptz } from "./columns.ts";
import { organization, user } from "./auth-schema.ts";

// Accounts, sessions, organizations, members and invitations: Better Auth's tables, generated by
// `deno task db:auth-schema` into auth-schema.ts. Never edit that file by hand.
export * from "./auth-schema.ts";

// Cross-cutting tables every project gets. Feature tables live next to their module (src/modules/<name>/schema.ts).

/** Who did what, when. Append-only; written by the audit module (or any service). */
export const auditLog = pgTable("audit_log", {
  id: id(),
  organizationId: text("organization_id").references(() => organization.id, { onDelete: "set null" }),
  actorId: text("actor_id").references(() => user.id, { onDelete: "set null" }),
  action: text("action").notNull(), // "note.create", "member.remove"
  entityType: text("entity_type"),
  entityId: text("entity_id"),
  requestId: text("request_id"),
  metadata: jsonb("metadata").$type<Record<string, unknown>>().notNull().default({}),
  createdAt: createdAt(),
}, (t) => [index("audit_log_org_idx").on(t.organizationId, t.id)]);

export const fileStatus = pgEnum("file_status", ["pending", "ready"]);

/** Metadata of an object kept in S3-compatible storage; the bytes never live in Postgres. */
export const files = pgTable("files", {
  id: id(),
  organizationId: text("organization_id").notNull().references(() => organization.id, { onDelete: "cascade" }),
  ownerId: text("owner_id").references(() => user.id, { onDelete: "set null" }),
  key: text("key").notNull(),
  filename: text("filename").notNull(),
  contentType: text("content_type").notNull(),
  sizeBytes: bigint("size_bytes", { mode: "number" }),
  status: fileStatus("status").notNull().default("pending"),
  createdAt: createdAt(),
  deletedAt: deletedAt(),
}, (t) => [uniqueIndex("files_key_idx").on(t.key), index("files_org_idx").on(t.organizationId, t.id)]);

/** In-app notifications (and the source for push). `data` is a small JSON payload for deep links. */
export const notifications = pgTable("notifications", {
  id: id(),
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  organizationId: text("organization_id").references(() => organization.id, { onDelete: "cascade" }),
  kind: text("kind").notNull(),
  title: text("title").notNull(),
  body: text("body"),
  data: jsonb("data").$type<Record<string, unknown>>().notNull().default({}),
  readAt: timestamptz("read_at"),
  createdAt: createdAt(),
}, (t) => [index("notifications_user_idx").on(t.userId, t.id)]);

/** Replay store for the Idempotency-Key header: one row per (user, key). */
export const idempotencyKeys = pgTable("idempotency_keys", {
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  key: text("key").notNull(),
  requestHash: text("request_hash").notNull(),
  status: integer("status"),
  body: text("body"),
  createdAt: createdAt(),
}, (t) => [uniqueIndex("idempotency_user_key_idx").on(t.userId, t.key)]);
